// Package server wires the services/api HTTP surface (ADR-0043). Routing +
// ServerInterface are generated by oapi-codegen (gen.go, `task codegen`, config
// oapi-codegen.api.yaml); this file implements that interface. Bodies use the
// internal/resource domain types (the store carries created_at/updated_at not on
// the wire); the generated body models are not used — same rationale as
// audit-service (see oapi-codegen.api.yaml).
//
// Auth posture for the operator-facing SPA (ADR-0047, T-007b):
//
//   - The PASETO session token is set in an HttpOnly cookie by Login and never
//     returned in the response body.  Service-to-service callers continue to
//     send `Authorization: Bearer <paseto>` directly (no cookie).
//   - A non-HttpOnly `aireos_csrf` cookie carries a per-session random value;
//     the SPA reads it via document.cookie and echoes it as `X-CSRF-Token` on
//     every non-GET/HEAD request (double-submit defense).
//   - Sliding refresh: when an operator's verified token has less than half of
//     its TTL remaining, slidingRefresh rotates both cookies inline with the
//     response.  ADR-0046's 8h operator TTL ⇒ refresh window is "< 4h
//     remaining."
//   - `mw.CookieToAuthHeader` (shared, packages/go/middleware) copies the session
//     cookie into the Authorization header for downstream RequireCapability. It
//     was promoted out of this file in T-018a so services/session-broker can
//     reuse it for the browser WebSocket upgrade (which cannot set headers).
package server

import (
	"context"
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"

	"github.com/go-chi/chi/v5"

	"aireos.local/packages/go/auth"
	mw "aireos.local/packages/go/middleware"
	"aireos.local/packages/go/outbox"
	"aireos.local/services/api/internal/gateway"
	"aireos.local/services/api/internal/policy"
	"aireos.local/services/api/internal/resource"
	"aireos.local/services/api/internal/session"
	"aireos.local/services/api/internal/store"
)

// Cookie + CSRF contract names (ADR-0047). The SPA in
// packages/shared-types/src/client.ts reads `aireos_csrf` from document.cookie
// and sends the value as the X-CSRF-Token header — change either name here
// and the SPA breaks. The CSRF header name is also the canonical lookup the
// chi-server stub uses on r.Header.Get below.
const (
	// sessionCookieName binds to the shared cross-service contract so the
	// cookie→Authorization adapter (now packages/go/middleware) and api's
	// cookie-writing code (Login/refresh/logout) cannot drift.
	sessionCookieName = mw.SessionCookieName
	csrfCookieName    = "aireos_csrf"
	csrfHeaderName    = "X-CSRF-Token"
)

// Store is the narrow slice of *store.Store the handlers need.
type Store interface {
	Create(ctx context.Context, in resource.Input) (resource.Resource, error)
	Get(ctx context.Context, id string) (resource.Resource, error)
	List(ctx context.Context, after string, limit int) ([]resource.Resource, string, error)
	Update(ctx context.Context, id string, in resource.Input) (resource.Resource, error)
	Delete(ctx context.Context, id string) error

	// Cockpit sessions (T-016b). All session reads/writes are operator-scoped:
	// the caller's capability subject is the operator_id, so one operator can
	// never see or end another's sessions (ADR-0048 §5).
	CreateSession(ctx context.Context, operatorID string, in session.CreateInput) (session.Session, error)
	GetSession(ctx context.Context, operatorID, id string) (session.Session, error)
	ListSessions(ctx context.Context, operatorID, after string, limit int) ([]session.Session, string, error)
	EndSession(ctx context.Context, operatorID, id string) (session.Session, error)

	// ParkForApproval inserts a session in 'pending_approval'; ApproveSession flips
	// it to 'pending' on approval; MarkClosed fail-closes / denies a parked session
	// (ADR-0054 / T-031b).
	ParkForApproval(ctx context.Context, operatorID string, in session.CreateInput) (session.Session, error)
	ApproveSession(ctx context.Context, operatorID, id string) (session.Session, error)
	MarkClosed(ctx context.Context, operatorID, id, reason string) (session.Session, error)

	// RecordEvent enqueues an audit evidence row into api's outbox (T-022 / SEC-9).
	RecordEvent(ctx context.Context, e outbox.Event) error
}

// policyDecider is the slice of *policy.Client the session handlers need: api
// consults policy-service at session-create (Decide) and on the operator's
// approve/deny (Resolve) (ADR-0054 §5). A nil decider means no decision point is
// configured — a requires_approval resource then fails closed.
type policyDecider interface {
	Decide(ctx context.Context, in policy.DecideInput) (policy.Decision, error)
	Resolve(ctx context.Context, sessionID, decision, resolvedBy string) (policy.ResolveResult, error)
}

// gatewayProxy is the slice of *gateway.Client the invocation-approval handlers
// proxy to (ADR-0057 §4): the operator's list + approve/deny on a parked MCP tool
// invocation. nil → no gateway is configured (the routes answer 503).
type gatewayProxy interface {
	ListPending(ctx context.Context) ([]gateway.PendingInvocation, error)
	Resolve(ctx context.Context, invocationID, decision, resolvedBy string) error
}

// Authenticator verifies operator credentials (services/api/internal/account).
type Authenticator interface {
	Authenticate(username, password string) (subject string, ok bool)
}

type apiHandlers struct {
	store  Store
	authn  Authenticator // nil → operator login disabled (503)
	signer *auth.Signer  // nil → operator login disabled (503)
	// agentSigner mints agent-tool tokens on the asymmetric agent plane (ADR-0060):
	// api holds the secret half, the gateway verifies with the public half. nil →
	// IssueAgentToken falls back to the symmetric signer (dev/transition).
	agentSigner *auth.AsymmetricSigner
	verifier    mw.Verifier   // used by Logout to attribute the actor from the cookie
	auditURL    string        // AIREOS_AUDIT_URL — the audit-timeline read-proxy upstream (T-024); "" disables it
	policy      policyDecider // POLICY_URL decision point (ADR-0054 / T-031b); nil → requires_approval resources fail closed
	gateway     gatewayProxy  // GATEWAY_URL invocation-approval proxy (ADR-0057 §4 / T-040b); nil → 503
	gatewayURL  string        // set by WithGateway; the client is built in New after all options apply (ADR-0060)
}

// Option configures optional, additively-wired dependencies on New without churning
// its positional signature (the cross-service URLs accreted over P1).
type Option func(*apiHandlers)

// WithGateway wires the mcp-gateway invocation-approval proxy (ADR-0057 §4). An empty
// baseURL is a no-op (the routes then answer 503), so callers can pass GATEWAY_URL
// unconditionally. The client itself is built in New after all options apply, so it
// can pick the agent-plane signer regardless of option order (ADR-0060).
func WithGateway(baseURL string) Option {
	return func(h *apiHandlers) { h.gatewayURL = baseURL }
}

// WithAgentSigner wires the asymmetric agent-plane signer (ADR-0060): api signs
// agent-tool tokens with this Ed25519 secret key so the gateway can verify them
// with the public half alone (a compromised gateway cannot mint). nil is a no-op —
// IssueAgentToken then falls back to the symmetric signer (dev/transition). Order-
// independent: it only stores the signer.
func WithAgentSigner(s *auth.AsymmetricSigner) Option {
	return func(h *apiHandlers) { h.agentSigner = s }
}

// agentIssuer is the IssueAgent behavior shared by the symmetric *auth.Signer and
// the asymmetric *auth.AsymmetricSigner, so IssueAgentToken can select either.
type agentIssuer interface {
	IssueAgent(subject, audience string, scope auth.Scope) (string, error)
}

// agentTokenIssuer prefers the asymmetric agent-plane signer (ADR-0060) when
// configured, else the symmetric signer (dev/transition). Returns nil only when
// neither is set (the concrete nils are checked before wrapping, so the returned
// interface is nil, not a typed-nil).
func (a *apiHandlers) agentTokenIssuer() agentIssuer {
	if a.agentSigner != nil {
		return a.agentSigner
	}
	if a.signer != nil {
		return a.signer
	}
	return nil
}

// New returns the api router. Routes that declared security in the contract are
// gated by RequireCapability over the human-agent (operator) and service-service
// edges; POST /v1/auth/login (security: []) and POST /v1/auth/logout
// (security: []) are public — see gateByDeclaredSecurity.
//
// Middleware order (effective flow at request time):
//
//	mw.CookieToAuthHeader — translate aireos_session cookie → Authorization
//	gateByDeclaredSecurity — RequireCapability + CSRF on gated mutations
//	slidingRefresh       — rotate cookies if operator token < half TTL
//
// The slice below is written innermost-first because the generated
// ServerInterfaceWrapper composes middlewares with `handler = m(handler)` per
// iteration — so the LAST entry becomes the outermost wrapper at runtime
// (see gen.go's per-op middleware loop). Reordering this slice without
// understanding that loop will silently break the cookie path.
func New(s Store, authn Authenticator, signer *auth.Signer, v mw.Verifier, auditURL, policyURL string, opts ...Option) http.Handler {
	h := &apiHandlers{store: s, authn: authn, signer: signer, verifier: v, auditURL: auditURL}
	if policyURL != "" {
		// The decision point is consulted at session-create for requires_approval
		// resources (ADR-0054). api mints a service-service token from its signer.
		h.policy = policy.NewClient(policyURL, signer)
	}
	for _, opt := range opts {
		opt(h)
	}
	// Build the gateway client after options apply so it picks the asymmetric
	// agent-plane signer when configured (ADR-0060), else the symmetric signer —
	// order-independent (WithGateway/WithAgentSigner may be passed in any order). A
	// concrete non-nil signer or an untyped nil is passed, never a typed-nil.
	if h.gatewayURL != "" {
		switch {
		case h.agentSigner != nil:
			h.gateway = gateway.NewClient(h.gatewayURL, h.agentSigner)
		case h.signer != nil:
			h.gateway = gateway.NewClient(h.gatewayURL, h.signer)
		default:
			h.gateway = gateway.NewClient(h.gatewayURL, nil)
		}
	}
	return HandlerWithOptions(h, ChiServerOptions{
		BaseRouter: chi.NewRouter(),
		Middlewares: []MiddlewareFunc{
			slidingRefresh(signer, s),                                // innermost  (last to run, closest to handler)
			gateByDeclaredSecurity(v),                                // middle
			MiddlewareFunc(mw.CookieToAuthHeader(sessionCookieName)), // outermost  (first to run)
		},
	})
}

// gateByDeclaredSecurity enforces RequireCapability on operations that declared
// security in the contract (the generated wrapper marks them with
// BearerAuthScopes in the request context). It additionally requires a valid
// double-submit CSRF token on mutating requests that authenticated via the
// session cookie. Service-to-service callers (Authorization header, no cookie)
// are exempt from CSRF — there's no browser to defend.
func gateByDeclaredSecurity(v mw.Verifier) MiddlewareFunc {
	require := mw.RequireCapability(v, "human-agent", "service-service")
	return func(next http.Handler) http.Handler {
		afterAuth := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if needsCSRF(r) && !csrfValid(r) {
				writeError(w, http.StatusForbidden, "forbidden", "csrf token missing or mismatched")
				return
			}
			next.ServeHTTP(w, r)
		})
		enforced := require(afterAuth)
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if r.Context().Value(BearerAuthScopes) != nil {
				enforced.ServeHTTP(w, r)
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

func needsCSRF(r *http.Request) bool {
	switch r.Method {
	case http.MethodGet, http.MethodHead, http.MethodOptions:
		return false
	}
	// Browser path = the request carried a session cookie. Service-service
	// path = Authorization-only, no cookie → no CSRF.
	_, err := r.Cookie(sessionCookieName)
	return err == nil
}

func csrfValid(r *http.Request) bool {
	header := r.Header.Get(csrfHeaderName)
	if header == "" {
		return false
	}
	c, err := r.Cookie(csrfCookieName)
	if err != nil || c.Value == "" {
		return false
	}
	// Constant-time compare via stdlib to avoid byte-by-byte timing oracles on
	// the CSRF value. ConstantTimeCompare returns 0/1, not bool.
	return subtle.ConstantTimeCompare([]byte(header), []byte(c.Value)) == 1
}

// slidingRefresh rotates the session + CSRF cookies inline with the response
// when an operator's token has less than half its TTL remaining (ADR-0047 §6,
// ADR-0046 OperatorTTL = 8h ⇒ refresh window < 4h). Service-service tokens are
// not refreshed (they self-refresh in-process). A nil signer (dev allow-all)
// short-circuits.
func slidingRefresh(signer *auth.Signer, s Store) MiddlewareFunc {
	if signer == nil {
		return func(next http.Handler) http.Handler { return next }
	}
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			cap, ok := mw.CapabilityFromContext(r.Context())
			if ok && cap.Edge == "human-agent" && !cap.ExpiresAt.IsZero() {
				remaining := time.Until(cap.ExpiresAt)
				if remaining > 0 && remaining < auth.OperatorTTL/2 {
					if newToken, err := signer.IssueOperator(cap.Subject, cap.Audience); err == nil {
						// Refresh is best-effort: if the cookie write fails
						// (rand failure, header already flushed), continue
						// serving the response — the next request will retry
						// the rotation if still in the refresh window.
						if setSessionCookies(w, newToken) == nil {
							recordAuth(r.Context(), s, cap.Subject, "auth.refresh") // SEC-9
						}
					}
				}
			}
			next.ServeHTTP(w, r)
		})
	}
}

// recordAuth best-effort enqueues an auth audit event (SEC-9) into api's outbox.
// Failure to enqueue must never fail the auth operation — a degraded audit path
// surfaces as growing outbox depth (ADR-0045), so we log and continue.
func recordAuth(ctx context.Context, s Store, subject, outcome string) {
	if err := s.RecordEvent(ctx, outbox.Event{
		Timestamp: time.Now(),
		Actor:     subject,
		Edge:      "human-agent",
		Target:    subject,
		Outcome:   outcome,
	}); err != nil {
		log.Printf("audit: enqueue %s for %s failed: %v", outcome, subject, err)
	}
}

// bearerFromHeader extracts the bearer token from Authorization (set from the
// session cookie by mw.CookieToAuthHeader, which runs for every route).
func bearerFromHeader(r *http.Request) string {
	h := r.Header.Get("Authorization")
	const p = "Bearer "
	if len(h) > len(p) && strings.EqualFold(h[:len(p)], p) {
		return strings.TrimSpace(h[len(p):])
	}
	return ""
}

// setSessionCookies writes the session + CSRF cookies on a successful login
// or a sliding refresh. Cookie attributes are ADR-0047 §Decision:
//   - HttpOnly on the session cookie (PASETO opaque to JS by construction).
//   - SameSite=Strict on both (primary CSRF defense; double-submit is layered).
//   - Secure on both (HTTPS-only; modern browsers treat localhost as secure).
//   - Path=/ so both apply to every SPA / API path under the same origin.
//   - MaxAge = OperatorTTL seconds.
func setSessionCookies(w http.ResponseWriter, token string) error {
	csrf, err := newCSRFToken()
	if err != nil {
		return err
	}
	maxAge := int(auth.OperatorTTL / time.Second)
	http.SetCookie(w, &http.Cookie{
		Name:     sessionCookieName,
		Value:    token,
		Path:     "/",
		MaxAge:   maxAge,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
	})
	http.SetCookie(w, &http.Cookie{
		Name:     csrfCookieName,
		Value:    csrf,
		Path:     "/",
		MaxAge:   maxAge,
		HttpOnly: false, // SPA reads this to echo X-CSRF-Token.
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
	})
	return nil
}

func clearSessionCookies(w http.ResponseWriter) {
	for _, name := range []string{sessionCookieName, csrfCookieName} {
		http.SetCookie(w, &http.Cookie{
			Name:     name,
			Value:    "",
			Path:     "/",
			MaxAge:   -1, // delete
			HttpOnly: name == sessionCookieName,
			Secure:   true,
			SameSite: http.SameSiteStrictMode,
		})
	}
}

func newCSRFToken() (string, error) {
	var b [32]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	return hex.EncodeToString(b[:]), nil
}

// Login (POST /v1/auth/login) verifies operator credentials and establishes
// the session by setting an HttpOnly session cookie + a non-HttpOnly CSRF
// cookie (ADR-0046, ADR-0047). The PASETO token is NOT returned in the body —
// it stays opaque to JS by construction. Public route.
func (a *apiHandlers) Login(w http.ResponseWriter, r *http.Request) {
	if a.authn == nil || a.signer == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "operator login is not configured")
		return
	}
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := dec.Decode(&req); err != nil || req.Username == "" || req.Password == "" {
		writeError(w, http.StatusBadRequest, "bad_request", "username and password are required")
		return
	}
	subject, ok := a.authn.Authenticate(req.Username, req.Password)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid credentials")
		return
	}
	// Operator tokens are scoped to this gateway's audience ("api").
	token, err := a.signer.IssueOperator(subject, "api")
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "issue token failed")
		return
	}
	if err := setSessionCookies(w, token); err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "set cookies failed")
		return
	}
	recordAuth(r.Context(), a.store, subject, "auth.login.success") // SEC-9
	writeJSON(w, http.StatusOK, map[string]string{
		"expiresAt": time.Now().Add(auth.OperatorTTL).UTC().Format(time.RFC3339),
	})
}

// Logout (POST /v1/auth/logout) clears the session + CSRF cookies. Public:
// callers with stale/expired cookies can recover. SameSite=Strict on the
// session cookie blocks cross-site CSRF on this endpoint at the browser layer.
func (a *apiHandlers) Logout(w http.ResponseWriter, r *http.Request) {
	// Best-effort actor attribution for the audit event: mw.CookieToAuthHeader has
	// copied the session cookie into Authorization (it runs on every route), so
	// verify it to name the operator. An absent/expired cookie → "operator:unknown".
	subject := "operator:unknown"
	if a.verifier != nil {
		if bearer := bearerFromHeader(r); bearer != "" {
			if c, err := a.verifier.Verify(r.Context(), bearer); err == nil && c.Subject != "" {
				subject = c.Subject
			}
		}
	}
	clearSessionCookies(w)
	recordAuth(r.Context(), a.store, subject, "auth.logout") // SEC-9
	w.WriteHeader(http.StatusNoContent)
}

// GetMe (GET /v1/auth/me) returns the verified capability of the current token.
func (a *apiHandlers) GetMe(w http.ResponseWriter, r *http.Request) {
	c, ok := mw.CapabilityFromContext(r.Context())
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"subject": c.Subject, "edge": c.Edge})
}

func (a *apiHandlers) decodeInput(w http.ResponseWriter, r *http.Request) (resource.Input, bool) {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields() // rejects a client-supplied id with 400
	var in resource.Input
	if err := dec.Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid request body: "+err.Error())
		return resource.Input{}, false
	}
	if err := in.Validate(); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", err.Error())
		return resource.Input{}, false
	}
	return in, true
}

func (a *apiHandlers) CreateResource(w http.ResponseWriter, r *http.Request) {
	in, ok := a.decodeInput(w, r)
	if !ok {
		return
	}
	res, err := a.store.Create(r.Context(), in)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "create failed")
		return
	}
	writeJSON(w, http.StatusCreated, res)
}

type resourcePage struct {
	Items []resource.Resource `json:"items"`
	Page  pageMeta            `json:"page"`
}

type pageMeta struct {
	NextCursor string `json:"nextCursor,omitempty"`
}

func (a *apiHandlers) ListResources(w http.ResponseWriter, r *http.Request, params ListResourcesParams) {
	limit := 50
	if params.Limit != nil {
		n := int(*params.Limit)
		if n < 1 || n > 200 {
			writeError(w, http.StatusBadRequest, "bad_request", "limit must be an integer in [1,200]")
			return
		}
		limit = n
	}
	var after string
	if params.Cursor != nil {
		after = string(*params.Cursor)
	}
	items, last, err := a.store.List(r.Context(), after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "list failed")
		return
	}
	page := resourcePage{Items: items}
	if len(items) == limit {
		page.Page.NextCursor = last
	}
	writeJSON(w, http.StatusOK, page)
}

func (a *apiHandlers) GetResource(w http.ResponseWriter, r *http.Request, id string) {
	res, err := a.store.Get(r.Context(), id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "get failed")
		return
	}
	writeJSON(w, http.StatusOK, res)
}

func (a *apiHandlers) UpdateResource(w http.ResponseWriter, r *http.Request, id string) {
	in, ok := a.decodeInput(w, r)
	if !ok {
		return
	}
	res, err := a.store.Update(r.Context(), id, in)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "update failed")
		return
	}
	writeJSON(w, http.StatusOK, res)
}

func (a *apiHandlers) DeleteResource(w http.ResponseWriter, r *http.Request, id string) {
	err := a.store.Delete(r.Context(), id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "delete failed")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// operatorSubject pulls the verified capability subject out of the request
// context (populated by RequireCapability). It is the session owner key. A
// missing capability on a gated route should be impossible — the gate runs
// first — but we fail closed with 401 rather than minting sessions under an
// empty operator id.
func operatorSubject(r *http.Request) (string, bool) {
	c, ok := mw.CapabilityFromContext(r.Context())
	if !ok || c.Subject == "" {
		return "", false
	}
	return c.Subject, true
}

// CreateSession (POST /v1/sessions) records the operator's intent to start a
// session against a resource. For a normal resource the row is created 'pending'
// and the broker activates it on a successful PTY attach. For a resource labeled
// requires_approval=true (ADR-0054) the session is instead parked
// 'pending_approval' and the policy decision point is consulted; the operator
// approves/denies via T-031b-ii. An unknown resourceId answers 404.
func (a *apiHandlers) CreateSession(w http.ResponseWriter, r *http.Request) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields() // rejects a client-supplied id/status/operatorId with 400
	var in session.CreateInput
	if err := dec.Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid request body: "+err.Error())
		return
	}
	in.Normalize()
	if err := in.Validate(); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", err.Error())
		return
	}

	// Read the resource to decide whether this start needs approval (ADR-0054:
	// trigger = a resource labeled requires_approval=true). This also resolves an
	// unknown resourceId to 404 before any session insert.
	res, err := a.store.Get(r.Context(), in.ResourceID)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "create session failed")
		return
	}

	if res.Labels["requires_approval"] != "true" {
		sess, err := a.store.CreateSession(r.Context(), operator, in)
		if errors.Is(err, store.ErrNotFound) {
			writeError(w, http.StatusNotFound, "not_found", "resource not found")
			return
		}
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal", "create session failed")
			return
		}
		writeJSON(w, http.StatusCreated, sess)
		return
	}

	a.createWithApproval(w, r, operator, in)
}

// createWithApproval parks a session-start to a requires_approval resource and
// consults the policy decision point (ADR-0054). The session is created
// 'pending_approval' FIRST (so the broker's status guard blocks any WS attach),
// then policy is consulted; any failure to obtain a requires_approval decision
// fail-closes the session ('closed'/policy_unavailable) — a flagged session never
// proceeds without an explicit operator approval (driven in T-031b-ii).
func (a *apiHandlers) createWithApproval(w http.ResponseWriter, r *http.Request, operator string, in session.CreateInput) {
	sess, err := a.store.ParkForApproval(r.Context(), operator, in)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "create session failed")
		return
	}

	if a.policy == nil {
		a.failClosed(r.Context(), operator, sess.ID)
		writeError(w, http.StatusServiceUnavailable, "unavailable", "approval required but the policy decision point is not configured")
		return
	}
	decision, derr := a.policy.Decide(r.Context(), policy.DecideInput{
		SessionID: sess.ID, Subject: operator, Edge: "agent-remote-session",
		Target: "resource:" + in.ResourceID, Action: "session.start", RequiresApproval: true,
	})
	if derr != nil {
		a.failClosed(r.Context(), operator, sess.ID)
		writeError(w, http.StatusBadGateway, "bad_gateway", "policy decision point unavailable")
		return
	}
	if decision.Decision != policy.DecisionRequiresApproval {
		// v0.2.0: a flagged resource always requires approval; any other decision is
		// an unexpected policy contract state — fail closed rather than proceed.
		a.failClosed(r.Context(), operator, sess.ID)
		writeError(w, http.StatusBadGateway, "bad_gateway", "unexpected policy decision")
		return
	}
	writeJSON(w, http.StatusCreated, sess) // parked pending_approval; operator resolves in T-031b-ii
}

// failClosed best-effort closes a parked session whose approval could not be
// obtained, so a policy outage does not leave it orphaned in 'pending_approval'.
func (a *apiHandlers) failClosed(ctx context.Context, operator, id string) {
	if _, err := a.store.MarkClosed(ctx, operator, id, session.ReasonPolicyUnavailable); err != nil {
		log.Printf("fail-closed MarkClosed(%s): %v", id, err)
	}
}

type sessionPage struct {
	Items []session.Session `json:"items"`
	Page  pageMeta          `json:"page"`
}

// ListSessions (GET /v1/sessions) returns a page of the caller's own sessions
// (operator-scoped; no cross-operator scope at v0.1.0).
func (a *apiHandlers) ListSessions(w http.ResponseWriter, r *http.Request, params ListSessionsParams) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	limit := 50
	if params.Limit != nil {
		n := int(*params.Limit)
		if n < 1 || n > 200 {
			writeError(w, http.StatusBadRequest, "bad_request", "limit must be an integer in [1,200]")
			return
		}
		limit = n
	}
	var after string
	if params.Cursor != nil {
		after = string(*params.Cursor)
	}
	items, last, err := a.store.ListSessions(r.Context(), operator, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "list sessions failed")
		return
	}
	page := sessionPage{Items: items}
	if len(items) == limit {
		page.Page.NextCursor = last
	}
	writeJSON(w, http.StatusOK, page)
}

// GetSession (GET /v1/sessions/{id}) returns session metadata the caller owns.
func (a *apiHandlers) GetSession(w http.ResponseWriter, r *http.Request, id string) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	sess, err := a.store.GetSession(r.Context(), operator, id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "session not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "get session failed")
		return
	}
	writeJSON(w, http.StatusOK, sess)
}

// EndSession (POST /v1/sessions/{id}/end) records the operator's intent to end a
// session. The transition is idempotent; the broker performs the real teardown
// and emits session.close (slice b).
func (a *apiHandlers) EndSession(w http.ResponseWriter, r *http.Request, id string) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	sess, err := a.store.EndSession(r.Context(), operator, id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "session not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "end session failed")
		return
	}
	writeJSON(w, http.StatusOK, sess)
}

// ResolveSession (POST /v1/sessions/{id}/resolve) records the operator's approve/
// deny on a session parked 'pending_approval' (ADR-0054; same-operator self-
// approval at v0.2.0). api consults policy-service (the decision authority) and
// then transitions its own session: approve → 'pending' (the broker may attach);
// deny → 'closed'/approval_denied. If policy reports no still-pending approval
// (already resolved or expired) api reconciles to 'closed'/approval_timeout (409);
// a policy outage leaves the session parked (502/503) so it never proceeds without
// an explicit approval. The approval itself is audit-chained by policy-service.
func (a *apiHandlers) ResolveSession(w http.ResponseWriter, r *http.Request, id string) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var body struct {
		Decision string `json:"decision"`
	}
	if err := dec.Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid request body: "+err.Error())
		return
	}
	if body.Decision != "approve" && body.Decision != "deny" {
		writeError(w, http.StatusBadRequest, "bad_request", "decision must be approve or deny")
		return
	}

	sess, err := a.store.GetSession(r.Context(), operator, id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "session not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "resolve session failed")
		return
	}
	if sess.Status != session.StatusPendingApproval {
		writeError(w, http.StatusConflict, "conflict", "session is not awaiting approval")
		return
	}
	if a.policy == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "the policy decision point is not configured")
		return
	}

	// Map the operator verb to the policy decision and resolve via the authority.
	polDecision := "granted"
	if body.Decision == "deny" {
		polDecision = "denied"
	}
	if _, rerr := a.policy.Resolve(r.Context(), id, polDecision, operator); rerr != nil {
		if errors.Is(rerr, policy.ErrNotPending) {
			// The approval expired (policy auto-denied) before the operator acted —
			// reconcile the parked session to closed and report the conflict.
			if closed, cerr := a.store.MarkClosed(r.Context(), operator, id, session.ReasonApprovalTimeout); cerr == nil {
				_ = closed
			}
			writeError(w, http.StatusConflict, "conflict", "approval expired")
			return
		}
		// Policy outage — leave the session parked so the operator can retry.
		writeError(w, http.StatusBadGateway, "bad_gateway", "policy decision point unavailable")
		return
	}

	if body.Decision == "approve" {
		approved, err := a.store.ApproveSession(r.Context(), operator, id)
		if errors.Is(err, store.ErrNotFound) {
			writeError(w, http.StatusConflict, "conflict", "session is not awaiting approval")
			return
		}
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal", "resolve session failed")
			return
		}
		writeJSON(w, http.StatusOK, approved)
		return
	}
	denied, err := a.store.MarkClosed(r.Context(), operator, id, session.ReasonApprovalDenied)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "resolve session failed")
		return
	}
	writeJSON(w, http.StatusOK, denied)
}

// IssueAgentToken (POST /v1/agent-tokens) mints a scoped agent-tool capability
// token for an autonomous agent (AG-1..3; ADR-0056/0057). Operator-gated
// (human-agent edge via the shared capability gate) + double-submit CSRF: an
// operator provisions the agent's short-lived (5-min) token, scoped to the
// resource(s) it may use (SEC-16). The token's audience is the MCP gateway, so the
// agent presents it as Bearer to services/mcp-gateway. The mint is audit-chained
// (auth.agent-token.mint, actor=operator, target=agent:<id>).
//
// A CLI sibling (task auth -- issue-agent) for offline/break-glass bootstrap is
// deferred (trigger: installed-stack offline agent provisioning); it would reuse
// the same IssueAgent primitive. The token is signed on the asymmetric agent plane
// (ADR-0060) when api is configured with an agent-plane key, else the symmetric
// signer (dev/transition) — agentTokenIssuer selects.
func (a *apiHandlers) IssueAgentToken(w http.ResponseWriter, r *http.Request) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	issuer := a.agentTokenIssuer()
	if issuer == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "token issuance not configured")
		return
	}
	var req struct {
		AgentID    string   `json:"agentId"`
		ResourceID string   `json:"resourceId"`
		Operations []string `json:"operations"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid JSON body")
		return
	}
	if req.AgentID == "" || req.ResourceID == "" {
		writeError(w, http.StatusBadRequest, "bad_request", "agentId and resourceId are required")
		return
	}
	subject := "agent:" + req.AgentID
	token, err := issuer.IssueAgent(subject, "mcp-gateway", auth.Scope{Resource: req.ResourceID, Operations: req.Operations})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "could not mint agent token")
		return
	}
	expiresAt := time.Now().Add(auth.AgentTTL)
	// Audit the mint (SEC-9 / AG-3): the operator is the actor, the agent the
	// target. Best-effort, like the other auth events.
	if err := a.store.RecordEvent(r.Context(), outbox.Event{
		Timestamp: time.Now(),
		Actor:     operator,
		Edge:      "human-agent",
		Target:    subject,
		Outcome:   "auth.agent-token.mint",
	}); err != nil {
		log.Printf("audit: enqueue auth.agent-token.mint for %s failed: %v", subject, err)
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"token":     token,
		"expiresAt": expiresAt.UTC().Format(time.RFC3339),
	})
}

// ListInvocations (GET /v1/invocations) proxies the operator's pending-tool-invocation
// list to the mcp-gateway internal plane (ADR-0057 §4 / T-040b). The operator is
// authenticated by the shared capability gate (human-agent); api then calls the
// gateway with its OWN service-service token. The list carries each invocation's
// command (ADR-0059) — operator-only, never on the agent plane.
func (a *apiHandlers) ListInvocations(w http.ResponseWriter, r *http.Request) {
	if _, ok := operatorSubject(r); !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	if a.gateway == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "the invocation gateway is not configured")
		return
	}
	invs, err := a.gateway.ListPending(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, "bad_gateway", "the invocation gateway is unavailable")
		return
	}
	if invs == nil {
		invs = []gateway.PendingInvocation{}
	}
	writeJSON(w, http.StatusOK, map[string]any{"invocations": invs})
}

// ResolveInvocation (POST /v1/invocations/{id}/resolve) proxies the operator's
// approve/deny on a parked tool invocation to the gateway (AP-2; ADR-0057 §4). api
// owns the operator verb (approve|deny → policy granted|denied) + the CSRF/cookie
// (ADR-0050); the gateway owns the reconcile, so api maps its status straight through:
// 404 unknown, 409 not-pending (already resolved / timed out), 502 gateway outage. The
// approval itself is audit-chained by policy-service (via the gateway), not here.
func (a *apiHandlers) ResolveInvocation(w http.ResponseWriter, r *http.Request, id string) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	if a.gateway == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "the invocation gateway is not configured")
		return
	}
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var body struct {
		Decision string `json:"decision"`
	}
	if err := dec.Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid request body: "+err.Error())
		return
	}
	var polDecision string
	switch body.Decision {
	case "approve":
		polDecision = "granted"
	case "deny":
		polDecision = "denied"
	default:
		writeError(w, http.StatusBadRequest, "bad_request", "decision must be approve or deny")
		return
	}

	switch err := a.gateway.Resolve(r.Context(), id, polDecision, operator); {
	case err == nil:
		writeJSON(w, http.StatusOK, map[string]string{"status": "resolved"})
	case errors.Is(err, gateway.ErrNotFound):
		writeError(w, http.StatusNotFound, "not_found", "invocation not found")
	case errors.Is(err, gateway.ErrNotPending):
		writeError(w, http.StatusConflict, "conflict", "invocation is not awaiting approval")
	default:
		writeError(w, http.StatusBadGateway, "bad_gateway", "the invocation gateway is unavailable")
	}
}

// ListAuditEvents (GET /v1/audit/events) is the operator audit-timeline read-proxy
// (T-024). The operator is authenticated by the shared capability gate (human-agent
// edge); api then reads audit-service with its OWN service token, so the chain
// authority's write gate stays strict service-only and never accepts operator
// tokens. The chain-authority page response is passed through verbatim (same
// {items, page} envelope as audit-service's /v1/events).
func (a *apiHandlers) ListAuditEvents(w http.ResponseWriter, r *http.Request, params ListAuditEventsParams) {
	if _, ok := operatorSubject(r); !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	if a.auditURL == "" {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "audit timeline not configured")
		return
	}
	q := url.Values{}
	if params.Limit != nil {
		q.Set("limit", strconv.Itoa(int(*params.Limit)))
	}
	if params.Cursor != nil && string(*params.Cursor) != "" {
		q.Set("cursor", string(*params.Cursor))
	}
	upstream := strings.TrimRight(a.auditURL, "/") + "/v1/events"
	if len(q) > 0 {
		upstream += "?" + q.Encode()
	}
	req, err := http.NewRequestWithContext(r.Context(), http.MethodGet, upstream, nil)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "build audit request failed")
		return
	}
	// api reads with its own service token (workload "api", audience "audit-service").
	if a.signer != nil {
		if tok, terr := a.signer.IssueService("api", "audit-service"); terr == nil {
			req.Header.Set("Authorization", "Bearer "+tok)
		}
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		writeError(w, http.StatusBadGateway, "bad_gateway", "audit timeline upstream unreachable")
		return
	}
	defer func() { _ = resp.Body.Close() }()
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(resp.StatusCode)
	_, _ = io.Copy(w, resp.Body)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]string{"code": code, "message": message})
}
